import { generateKeyPairSync } from 'node:crypto';
import { TrustedKeyring, type KeyRole, type TrustedKeyInput } from '../trust.ts';

/** Test-only: fresh ed25519 identities. Production keys are provisioned by the operator, never generated by the runtime. */
export function testIdentity(keyId: string, principalId: string, roles: readonly KeyRole[], extra: Partial<TrustedKeyInput> = {}) {
  const { publicKey, privateKey } = generateKeyPairSync('ed25519');
  const publicKeyPem = publicKey.export({ type: 'spki', format: 'pem' }).toString();
  const privateKeyPem = privateKey.export({ type: 'pkcs8', format: 'pem' }).toString();
  return { keyId, principalId, roles, privateKeyPem, input: { keyId, principalId, roles, publicKeyPem, ...extra } satisfies TrustedKeyInput };
}
export const keyringOf = (...ids: ReturnType<typeof testIdentity>[]) => new TrustedKeyring(ids.map((i) => i.input));
